# Rebuilds the two Pixelwright textures from the exact rows written in the studio
from PIL import Image
PAL={'a':'#525e6a','b':'#76838f','c':'#9aa7b2','d':'#bcc7cf','e':'#d8e0e6','f':'#eef3f6','p':'#844626','q':'#ac6436','r':'#cf8a52','n':'#1c5866','g':'#2a8ea2','h':'#46c4d8','i':'#8ae6f0'}
def draw(im,origin,rows):
    ox,oy=origin
    for j,r in enumerate(rows):
        r=r.replace('|','')
        for i,ch in enumerate(r):
            if ch in PAL:
                h=PAL[ch];im.putpixel((ox+i,oy+j),(int(h[1:3],16),int(h[3:5],16),int(h[5:7],16),255))
